!function(){"use strict";const i={nilgiri:{title:"Nilgiri Hills",desc:"The core range of the Nilgiri Pipit. The montane grasslands around Ooty, Doddabetta, and Mukurthi support the largest known populations. Mukurthi National Park specifically protects high-altitude grassland habitat for both the pipit and the Nilgiri Tahr."},eravikulam:{title:"Eravikulam National Park",desc:"Located in the Anaimalai Hills of Kerala, Eravikulam is famous for the Nilgiri Tahr but also supports a healthy population of Nilgiri Pipit in its high-altitude grasslands. The park's grassland restoration programme has directly benefited the pipit."},mukurthi:{title:"Mukurthi National Park",desc:"A 78 km² protected area in the Nilgiri district specifically designated for shola-grassland conservation. The park is one of the most important strongholds for the Nilgiri Pipit, with its high-altitude plateaus providing ideal foraging and nesting habitat."},anaimalai:{title:"Anaimalai Hills",desc:"The southern extension of the pipit's range. The high-altitude grasslands around Valparai and the Anaimalai Tiger Reserve periphery support scattered populations, though habitat loss from tea and cardamom plantations has reduced connectivity."},palani:{title:"Palani Hills",desc:"The grasslands around Kodaikanal in the Palani Hills support an isolated population of Nilgiri Pipit. This population is genetically distinct from the Nilgiri population, suggesting long-term isolation on this separate sky island."}};document.addEventListener("DOMContentLoaded",()=>{!function(){const t=document.querySelectorAll(".map-marker"),e=document.getElementById("map-info-title"),n=document.getElementById("map-info-desc");if(!e||!n)return;const a=t=>{const a=i[t];a&&(e.textContent=a.title,n.textContent=a.desc)};t.forEach(i=>{const t=i.dataset.location;i.addEventListener("click",()=>a(t)),i.addEventListener("keydown",i=>{"Enter"!==i.key&&" "!==i.key||(i.preventDefault(),a(t))})})}(),function(){const i=document.querySelectorAll(".np-nav-link"),t=document.getElementById("np-section-nav");if(!t)return;const e=Array.from(i).map(i=>{const t=i.dataset.navTarget;return{link:i,section:document.getElementById(t)}}).filter(i=>i.section),n=t=>{i.forEach(i=>i.classList.remove("active")),t.classList.add("active")};i.forEach(i=>{i.addEventListener("click",t=>{n(i)})});const a=new IntersectionObserver(i=>{i.forEach(i=>{if(i.isIntersecting){const e=t.querySelector(`[data-nav-target="${i.target.id}"]`);e&&n(e)}})},{rootMargin:"-40% 0px -50% 0px"});e.forEach(i=>a.observe(i.section))}(),function(){const i=document.querySelectorAll(".reveal");if(!("IntersectionObserver"in window))return void i.forEach(i=>i.classList.add("visible"));const t=new IntersectionObserver(i=>{i.forEach(i=>{i.isIntersecting&&(i.target.classList.add("visible"),t.unobserve(i.target))})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});i.forEach(i=>t.observe(i))}(),window.Journey&&window.Journey.registerSearchItems("frontend/nilgiri-pipit-explorer/index.html",[{id:"nilgiri-pipit-main",title:"Nilgiri Pipit Explorer",description:"Explore the Nilgiri Pipit (Anthus nilghiriensis) — an endemic bird of the montane grasslands of southern India's Western Ghats, covering taxonomy, habitat, diet, behaviour, conservation status, threats, and references.",link:"frontend/nilgiri-pipit-explorer/index.html"},{id:"nilgiri-pipit-classification",title:"Nilgiri Pipit Taxonomy",description:"Scientific classification of the Nilgiri Pipit — Kingdom Animalia, Order Passeriformes, Family Motacillidae, described by Sharpe in 1885.",link:"frontend/nilgiri-pipit-explorer/index.html#classification"},{id:"nilgiri-pipit-conservation",title:"Nilgiri Pipit Conservation Status",description:"IUCN Vulnerable (VU) — the Nilgiri Pipit faces threats from climate change, plantation invasion of grasslands, overgrazing, and habitat fragmentation.",link:"frontend/nilgiri-pipit-explorer/index.html#conservation"}])})}();